-- ============================================================================
-- Guided Tours — Core Schema (14 Tables)
-- ============================================================================
-- Design: plans/guided-tours.md (§5.3, §6, §19, §20)
--
-- Tables (in dependency order):
--   1.  TourStepType        (MJ: Tour Step Types)
--   2.  TourSurface         (MJ: Tour Surfaces)
--   3.  Tour                (MJ: Tours)
--   4.  TourVersion         (MJ: Tour Versions) + FK_Tour_CurrentVersion
--   5.  TourSurfaceTour     (MJ: Tour Surface Tours)
--   6.  TourStep            (MJ: Tour Steps)
--   7.  TourStepPath        (MJ: Tour Step Paths)
--   8.  TourPrerequisite    (MJ: Tour Prerequisites)
--   9.  TourTrigger         (MJ: Tour Triggers)
--   10. TourLearningPath        (MJ: Tour Learning Paths)
--   11. TourLearningPathTourLink (MJ: Tour Learning Path Tour Links)
--   12. TourRun             (MJ: Tour Runs)
--   13. TourRunStep         (MJ: Tour Run Steps)
--   14. TourOverride        (MJ: Tour Overrides)
--
-- CodeGen owns: __mj_CreatedAt/__mj_UpdatedAt, FK indexes, base views,
-- stored procedures, EntityField rows, and value-list metadata derived from
-- CHECK constraints.
--
-- PostgreSQL counterpart is produced by the release build.
-- ============================================================================


-- ============================================================================
-- 1. TourStepType (MJ: Tour Step Types)
-- ============================================================================

CREATE TABLE ${flyway:defaultSchema}.TourStepType (
    ID UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_TourStepType_ID DEFAULT NEWSEQUENTIALID(),
    Name NVARCHAR(100) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL,
    Description NVARCHAR(MAX) COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    DriverClass NVARCHAR(255) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL,
    RendererClass NVARCHAR(255) COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    ComponentID UNIQUEIDENTIFIER NULL,
    ConfigSchema NVARCHAR(MAX) COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    SupportedModes NVARCHAR(100) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL CONSTRAINT DF_TourStepType_SupportedModes DEFAULT N'Show,Guide',
    IsAgentCapable BIT NOT NULL CONSTRAINT DF_TourStepType_IsAgentCapable DEFAULT 1,
    Icon NVARCHAR(100) COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    Status NVARCHAR(20) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL CONSTRAINT DF_TourStepType_Status DEFAULT N'Active',
    CONSTRAINT PK_TourStepType PRIMARY KEY (ID),
    CONSTRAINT UQ_TourStepType_Name UNIQUE (Name),
    CONSTRAINT FK_TourStepType_Component FOREIGN KEY (ComponentID) REFERENCES ${flyway:defaultSchema}.Component(ID),
    CONSTRAINT CK_TourStepType_Status CHECK (Status IN (N'Active', N'Deprecated', N'Disabled'))
);
GO


-- ============================================================================
-- 2. TourSurface (MJ: Tour Surfaces)
-- ============================================================================

CREATE TABLE ${flyway:defaultSchema}.TourSurface (
    ID UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_TourSurface_ID DEFAULT NEWSEQUENTIALID(),
    Name NVARCHAR(255) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL,
    SurfaceKey NVARCHAR(150) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL,
    Description NVARCHAR(MAX) COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    SurfaceType NVARCHAR(30) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL CONSTRAINT DF_TourSurface_SurfaceType DEFAULT N'Web Page',
    PublicKey NVARCHAR(150) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL,
    AllowedOrigins NVARCHAR(MAX) COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    AuthStrategy NVARCHAR(20) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL CONSTRAINT DF_TourSurface_AuthStrategy DEFAULT N'Guest',
    GuestRoleID UNIQUEIDENTIFIER NULL,
    ConversationWidgetInstanceID UNIQUEIDENTIFIER NULL,
    RateLimitPerMinute INT NOT NULL CONSTRAINT DF_TourSurface_RateLimitPerMinute DEFAULT 60,
    VisitorRetentionDays INT NULL,
    Status NVARCHAR(20) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL CONSTRAINT DF_TourSurface_Status DEFAULT N'Active',
    Configuration NVARCHAR(MAX) COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    CONSTRAINT PK_TourSurface PRIMARY KEY (ID),
    CONSTRAINT UQ_TourSurface_SurfaceKey UNIQUE (SurfaceKey),
    CONSTRAINT UQ_TourSurface_PublicKey UNIQUE (PublicKey),
    CONSTRAINT FK_TourSurface_GuestRole FOREIGN KEY (GuestRoleID) REFERENCES ${flyway:defaultSchema}.Role(ID),
    CONSTRAINT FK_TourSurface_ConversationWidgetInstance FOREIGN KEY (ConversationWidgetInstanceID) REFERENCES ${flyway:defaultSchema}.ConversationWidgetInstance(ID),
    CONSTRAINT CK_TourSurface_SurfaceType CHECK (SurfaceType IN (N'MJ Angular App', N'Web Page', N'Mobile App')),
    CONSTRAINT CK_TourSurface_AuthStrategy CHECK (AuthStrategy IN (N'MJ User', N'Guest', N'Either')),
    CONSTRAINT CK_TourSurface_RateLimitPerMinute CHECK (RateLimitPerMinute > 0),
    CONSTRAINT CK_TourSurface_VisitorRetentionDays CHECK (VisitorRetentionDays IS NULL OR VisitorRetentionDays > 0),
    CONSTRAINT CK_TourSurface_Status CHECK (Status IN (N'Active', N'Disabled', N'Retired'))
);
GO


-- ============================================================================
-- 3. Tour (MJ: Tours)
-- ============================================================================

CREATE TABLE ${flyway:defaultSchema}.Tour (
    ID UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_Tour_ID DEFAULT NEWSEQUENTIALID(),
    Name NVARCHAR(255) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL,
    TourKey NVARCHAR(150) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL,
    Description NVARCHAR(MAX) COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    ApplicationID UNIQUEIDENTIFIER NULL,
    RunInAuthenticatedHosts BIT NOT NULL CONSTRAINT DF_Tour_RunInAuthenticatedHosts DEFAULT 1,
    Status NVARCHAR(20) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL CONSTRAINT DF_Tour_Status DEFAULT N'Draft',
    CurrentVersionID UNIQUEIDENTIFIER NULL,
    EstimatedMinutes INT NULL,
    AudienceFilter NVARCHAR(MAX) COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    LaunchPolicy NVARCHAR(MAX) COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    Priority INT NOT NULL CONSTRAINT DF_Tour_Priority DEFAULT 100,
    ThrottleTags NVARCHAR(500) COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    DefaultGuideMode NVARCHAR(20) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL CONSTRAINT DF_Tour_DefaultGuideMode DEFAULT N'Visual',
    AllowAgentActions BIT NOT NULL CONSTRAINT DF_Tour_AllowAgentActions DEFAULT 0,
    GuideAgentID UNIQUEIDENTIFIER NULL,
    DriverClass NVARCHAR(255) COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    PresenterClass NVARCHAR(255) COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    Goal NVARCHAR(MAX) COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    StartLocation NVARCHAR(MAX) COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    VersionTag NVARCHAR(50) COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    Configuration NVARCHAR(MAX) COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    CONSTRAINT PK_Tour PRIMARY KEY (ID),
    CONSTRAINT UQ_Tour_TourKey UNIQUE (TourKey),
    CONSTRAINT FK_Tour_Application FOREIGN KEY (ApplicationID) REFERENCES ${flyway:defaultSchema}.Application(ID),
    CONSTRAINT FK_Tour_GuideAgent FOREIGN KEY (GuideAgentID) REFERENCES ${flyway:defaultSchema}.AIAgent(ID),
    CONSTRAINT CK_Tour_Status CHECK (Status IN (N'Draft', N'Active', N'Retired')),
    CONSTRAINT CK_Tour_EstimatedMinutes CHECK (EstimatedMinutes IS NULL OR EstimatedMinutes >= 0),
    CONSTRAINT CK_Tour_DefaultGuideMode CHECK (DefaultGuideMode IN (N'Visual', N'Chat', N'Voice', N'User Choice'))
);
GO


-- ============================================================================
-- 4. TourVersion (MJ: Tour Versions) & Tour.CurrentVersionID FK
