    PublishedAt DATETIMEOFFSET(7) NOT NULL CONSTRAINT DF_TourVersion_PublishedAt DEFAULT SYSDATETIMEOFFSET(),
    PublishedByUserID UNIQUEIDENTIFIER NULL,
    ChangeSummary NVARCHAR(MAX) COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    CONSTRAINT PK_TourVersion PRIMARY KEY (ID),
    CONSTRAINT UQ_TourVersion_Tour_Version UNIQUE (TourID, VersionNumber),
    CONSTRAINT FK_TourVersion_Tour FOREIGN KEY (TourID) REFERENCES ${flyway:defaultSchema}.Tour(ID),
    CONSTRAINT FK_TourVersion_PublishedByUser FOREIGN KEY (PublishedByUserID) REFERENCES ${flyway:defaultSchema}.[User](ID),
    CONSTRAINT CK_TourVersion_VersionNumber CHECK (VersionNumber > 0)
);
GO

ALTER TABLE ${flyway:defaultSchema}.Tour
    ADD CONSTRAINT FK_Tour_CurrentVersion
    FOREIGN KEY (CurrentVersionID) REFERENCES ${flyway:defaultSchema}.TourVersion(ID);
GO


