    Body NVARCHAR(MAX) COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    Configuration NVARCHAR(MAX) COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    Anchor NVARCHAR(MAX) COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    Placement NVARCHAR(30) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL CONSTRAINT DF_TourStep_Placement DEFAULT N'Auto',
    Mode NVARCHAR(20) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL CONSTRAINT DF_TourStep_Mode DEFAULT N'Guide',
    Prepare NVARCHAR(MAX) COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    Completion NVARCHAR(MAX) COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    SkipWhen NVARCHAR(MAX) COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    OnMissing NVARCHAR(20) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL CONSTRAINT DF_TourStep_OnMissing DEFAULT N'Center',
    IsOptional BIT NOT NULL CONSTRAINT DF_TourStep_IsOptional DEFAULT 0,
    GuideNotes NVARCHAR(MAX) COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    VoiceScript NVARCHAR(MAX) COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    CONSTRAINT PK_TourStep PRIMARY KEY (ID),
    CONSTRAINT UQ_TourStep_Tour_StepKey UNIQUE (TourID, StepKey),
    CONSTRAINT FK_TourStep_Tour FOREIGN KEY (TourID) REFERENCES ${flyway:defaultSchema}.Tour(ID),
    CONSTRAINT FK_TourStep_StepType FOREIGN KEY (StepTypeID) REFERENCES ${flyway:defaultSchema}.TourStepType(ID),
    CONSTRAINT CK_TourStep_Placement CHECK (Placement IN (N'Auto', N'Top', N'Bottom', N'Left', N'Right', N'Center')),
    CONSTRAINT CK_TourStep_Mode CHECK (Mode IN (N'Show', N'Guide', N'Do')),
    CONSTRAINT CK_TourStep_OnMissing CHECK (OnMissing IN (N'Skip', N'Center', N'Stall', N'Agent Recover'))
);
GO


