    CONSTRAINT PK_TourStepPath PRIMARY KEY (ID),
    CONSTRAINT FK_TourStepPath_Tour FOREIGN KEY (TourID) REFERENCES ${flyway:defaultSchema}.Tour(ID),
    CONSTRAINT FK_TourStepPath_FromStep FOREIGN KEY (FromStepID) REFERENCES ${flyway:defaultSchema}.TourStep(ID),
