-- ============================================================================
-- 9. TourTrigger (MJ: Tour Triggers)
-- ============================================================================
-- TriggerType is intentionally an open string (no CHECK constraint) resolved
-- via ClassFactory so apps can register custom triggers without migrations.

CREATE TABLE ${flyway:defaultSchema}.TourTrigger (
    ID UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_TourTrigger_ID DEFAULT NEWSEQUENTIALID(),
    TourID UNIQUEIDENTIFIER NOT NULL,
    TriggerType NVARCHAR(100) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL,
    Configuration NVARCHAR(MAX) COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    Delivery NVARCHAR(20) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL CONSTRAINT DF_TourTrigger_Delivery DEFAULT N'Offer',
    CooldownDays INT NULL,
    Priority INT NOT NULL CONSTRAINT DF_TourTrigger_Priority DEFAULT 100,
    Status NVARCHAR(20) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL CONSTRAINT DF_TourTrigger_Status DEFAULT N'Active',
    CONSTRAINT PK_TourTrigger PRIMARY KEY (ID),
    CONSTRAINT FK_TourTrigger_Tour FOREIGN KEY (TourID) REFERENCES ${flyway:defaultSchema}.Tour(ID),
    CONSTRAINT CK_TourTrigger_Delivery CHECK (Delivery IN (N'Offer', N'Beacon', N'Notification', N'Auto')),
    CONSTRAINT CK_TourTrigger_CooldownDays CHECK (CooldownDays IS NULL OR CooldownDays >= 0),
    CONSTRAINT CK_TourTrigger_Status CHECK (Status IN (N'Active', N'Paused', N'Disabled'))
);
GO


