    GuideMode NVARCHAR(20) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL CONSTRAINT DF_TourRun_GuideMode DEFAULT N'Visual',
    DirectorType NVARCHAR(100) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL CONSTRAINT DF_TourRun_DirectorType DEFAULT N'Visual',
    CurrentStepKey NVARCHAR(100) COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
