    CONSTRAINT CK_TourRun_GuideMode CHECK (GuideMode IN (N'Visual', N'Chat', N'Voice')),
    CONSTRAINT CK_TourRun_LaunchSource CHECK (LaunchSource IN (N'Launcher', N'Omnibar', N'Agent', N'Trigger', N'Notification', N'Link', N'Learning Path', N'Empty State'))
);
GO


