-- ============================================================================
-- 14. TourOverride (MJ: Tour Overrides)
-- ============================================================================

CREATE TABLE ${flyway:defaultSchema}.TourOverride (
    ID UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_TourOverride_ID DEFAULT NEWSEQUENTIALID(),
    TourID UNIQUEIDENTIFIER NOT NULL,
    Scope NVARCHAR(20) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL CONSTRAINT DF_TourOverride_Scope DEFAULT N'Global',
    RoleID UNIQUEIDENTIFIER NULL,
    UserID UNIQUEIDENTIFIER NULL,
    Precedence INT NOT NULL CONSTRAINT DF_TourOverride_Precedence DEFAULT 0,
    Status NVARCHAR(20) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL CONSTRAINT DF_TourOverride_Status DEFAULT N'Active',
    AudienceFilter NVARCHAR(MAX) COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    LaunchPolicy NVARCHAR(MAX) COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    IsDisabled BIT NOT NULL CONSTRAINT DF_TourOverride_IsDisabled DEFAULT 0,
    Configuration NVARCHAR(MAX) COLLATE SQL_Latin1_General_CP1_CI_AS NULL,
    CONSTRAINT PK_TourOverride PRIMARY KEY (ID),
    CONSTRAINT FK_TourOverride_Tour FOREIGN KEY (TourID) REFERENCES ${flyway:defaultSchema}.Tour(ID),
    CONSTRAINT FK_TourOverride_Role FOREIGN KEY (RoleID) REFERENCES ${flyway:defaultSchema}.Role(ID),
    CONSTRAINT FK_TourOverride_User FOREIGN KEY (UserID) REFERENCES ${flyway:defaultSchema}.[User](ID),
    CONSTRAINT CK_TourOverride_Scope CHECK (Scope IN (N'Global', N'Role', N'User')),
    CONSTRAINT CK_TourOverride_Status CHECK (Status IN (N'Active', N'Disabled')),
    CONSTRAINT CK_TourOverride_ScopeTarget CHECK (
        (Scope = N'Global' AND RoleID IS NULL AND UserID IS NULL) OR
        (Scope = N'Role' AND RoleID IS NOT NULL AND UserID IS NULL) OR
        (Scope = N'User' AND UserID IS NOT NULL AND RoleID IS NULL)
    )
);
GO


-- ============================================================================
-- 15. DESCRIPTIONS (MS_Description extended properties for every table & column)
-- ============================================================================

