------------------------------------------------------------
IF OBJECT_ID('[${flyway:defaultSchema}].[vwTourStepPaths]', 'V') IS NOT NULL
    DROP VIEW [${flyway:defaultSchema}].[vwTourStepPaths];
GO

CREATE VIEW [${flyway:defaultSchema}].[vwTourStepPaths]
AS
SELECT
    t.*,
    MJTour_TourID.[Name] AS [Tour],
    MJTourStep_FromStepID.[Title] AS [FromStep],
    MJTourStep_ToStepID.[Title] AS [ToStep]
FROM
    [${flyway:defaultSchema}].[TourStepPath] AS t
LEFT OUTER JOIN
    [${flyway:defaultSchema}].[Tour] AS MJTour_TourID
  ON
    [t].[TourID] = MJTour_TourID.[ID]
LEFT OUTER JOIN
    [${flyway:defaultSchema}].[TourStep] AS MJTourStep_FromStepID
  ON
    [t].[FromStepID] = MJTourStep_FromStepID.[ID]
LEFT OUTER JOIN
    [${flyway:defaultSchema}].[TourStep] AS MJTourStep_ToStepID
  ON
    [t].[ToStepID] = MJTourStep_ToStepID.[ID]
GO
